        "patch": "From da79ad6d83d5b1a79826cd93a8335a3463f88839 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:17:50 -0700\nSubject: [PATCH 2/3] Read gauge colors from theme tokens\n\nThe gauge set its colors inline from the light palette, so it stayed light in a dark page. It now uses the var(--rl-*) tokens, and the track tint uses color-mix() because a hex alpha suffix can't be appended to a CSS variable. The gauge test checks for the token instead of the light hex.\n---\n src/components/Gauge.tsx | 10 +++++-----\n test/gauge.test.tsx      |  6 +++---\n 2 files changed, 8 insertions(+), 8 deletions(-)\n\ndiff --git a/src/components/Gauge.tsx b/src/components/Gauge.tsx\nindex e5a6e6b..ff574b9 100644\n--- a/src/components/Gauge.tsx\n+++ b/src/components/Gauge.tsx\n@@ -1,5 +1,5 @@\n import { useState } from \"react\";\n-import { palette } from \"../theme/tokens\";\n+import { tokens } from \"../theme/tokens\";\n import type { GaugeKind } from \"../types\";\n \n export interface GaugeProps {\n@@ -40,11 +40,11 @@ export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"u\n   const span = max - min;\n   const pct = span > 0 ? Math.min(100, Math.max(0, ((value - min) / span) * 100)) : 0;\n   const alert = alertAt !== undefined && value >= alertAt;\n-  const barColor = alert ? palette.alert : palette.bar;\n+  const barColor = alert ? tokens.alert : tokens.bar;\n \n   return (\n     <div className=\"gauge\" data-kind={kind} data-alert={alert || undefined}>\n-      <span className=\"gauge-label\" style={{ color: palette.muted }}>\n+      <span className=\"gauge-label\" style={{ color: tokens.muted }}>\n         {label}\n       </span>\n       <div\n@@ -55,7 +55,7 @@ export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"u\n         aria-valuemax={max}\n         aria-valuenow={value}\n         aria-valuetext={reading}\n-        style={{ background: `${barColor}22` }}\n+        style={{ background: `color-mix(in srgb, ${barColor} 13%, transparent)` }}\n       >\n         <div className=\"gauge-bar\" style={{ width: `${Math.round(pct)}%`, background: barColor }} />\n       </div>\n@@ -64,7 +64,7 @@ export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"u\n         className=\"gauge-value\"\n         title={metric ? \"Show US units\" : \"Show metric units\"}\n         onClick={() => setUnits(metric ? \"us\" : \"metric\")}\n-        style={{ color: palette.ink }}\n+        style={{ color: tokens.ink }}\n       >\n         {reading}\n       </button>\ndiff --git a/test/gauge.test.tsx b/test/gauge.test.tsx\nindex d57d8b6..21ad69f 100644\n--- a/test/gauge.test.tsx\n+++ b/test/gauge.test.tsx\n@@ -1,7 +1,7 @@\n import { renderToString } from \"react-dom/server\";\n import { describe, expect, it } from \"vitest\";\n import { Gauge, type GaugeProps } from \"../src/components/Gauge\";\n-import { palette } from \"../src/theme/tokens\";\n+import { tokens } from \"../src/theme/tokens\";\n \n const stage: GaugeProps = { kind: \"stage\", label: \"Stage\", value: 6.2, min: 0, max: 10, alertAt: 9 };\n const flow: GaugeProps = { kind: \"flow\", label: \"Flow\", value: 4810, min: 0, max: 10000 };\n@@ -41,10 +41,10 @@ describe(\"Gauge\", () => {\n   it(\"switches to the alert color at the alert threshold\", () => {\n     const calm = html(stage);\n     expect(calm).not.toContain(\"data-alert\");\n-    expect(calm).toContain(`background:${palette.bar}`);\n+    expect(calm).toContain(`background:${tokens.bar}`);\n \n     const high = html({ ...stage, value: 9 });\n     expect(high).toContain('data-alert=\"true\"');\n-    expect(high).toContain(`background:${palette.alert}`);\n+    expect(high).toContain(`background:${tokens.alert}`);\n   });\n });\n",
