        "file": "0003-Test-the-dark-palette-s-coverage-and-contrast.patch",
        "patch": "From e3b04757b6c103d3757ff7d956dff3a314db4578 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:19:13 -0700\nSubject: [PATCH 3/3] Test the dark palette's coverage and contrast\n\nEvery light token has a dark value, the gauge emits only variable references, and text, bar and alert colors keep WCAG contrast on cards in both themes (4.5:1 for text, 3:1 for the bars).\n---\n test/theme.test.tsx | 40 ++++++++++++++++++++++++++++++++++++++++\n 1 file changed, 40 insertions(+)\n create mode 100644 test/theme.test.tsx\n\ndiff --git a/test/theme.test.tsx b/test/theme.test.tsx\nnew file mode 100644\nindex 0000000..1d2a034\n--- /dev/null\n+++ b/test/theme.test.tsx\n@@ -0,0 +1,40 @@\n+import { renderToString } from \"react-dom/server\";\n+import { describe, expect, it } from \"vitest\";\n+import { Gauge } from \"../src/components/Gauge\";\n+import { dark, light, type Palette } from \"../src/theme/tokens\";\n+\n+/** WCAG relative luminance contrast ratio of two #rrggbb colors. */\n+function contrast(a: string, b: string): number {\n+  const lum = (hex: string) => {\n+    const [r, g, b] = [1, 3, 5].map((i) => {\n+      const c = parseInt(hex.slice(i, i + 2), 16) / 255;\n+      return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;\n+    });\n+    return 0.2126 * r! + 0.7152 * g! + 0.0722 * b!;\n+  };\n+  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);\n+  return (hi! + 0.05) / (lo! + 0.05);\n+}\n+\n+describe(\"theme tokens\", () => {\n+  it(\"has a dark value for every light token\", () => {\n+    expect(Object.keys(dark).sort()).toEqual(Object.keys(light).sort());\n+  });\n+\n+  it(\"leaves the gauge's colors to the active theme\", () => {\n+    const html = renderToString(<Gauge kind=\"stage\" label=\"Stage\" value={9.2} min={0} max={10} alertAt={9} />);\n+    const styles = [...html.matchAll(/style=\"([^\"]*)\"/g)].map((m) => m[1]).join(\";\");\n+    expect(styles).toContain(\"var(--rl-alert)\");\n+    expect(styles).not.toMatch(/#[0-9a-f]{3,8}\b/i);\n+  });\n+\n+  it.each([\n+    [\"light\", light],\n+    [\"dark\", dark],\n+  ] as Array<[string, Palette]>)(\"keeps text readable on the %s cards\", (_, p) => {\n+    expect(contrast(p.ink, p.surface)).toBeGreaterThanOrEqual(4.5);\n+    expect(contrast(p.muted, p.surface)).toBeGreaterThanOrEqual(4.5);\n+    expect(contrast(p.bar, p.surface)).toBeGreaterThanOrEqual(3);\n+    expect(contrast(p.alert, p.surface)).toBeGreaterThanOrEqual(3);\n+  });\n+});\n",
