        "file": "0001-Detect-the-system-color-scheme.patch",
        "patch": "From 1aef90342cd3cdffe70a193e7886a238d2749881 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:23:59 -0700\nSubject: [PATCH 1/4] Detect the system color scheme\n\nuseColorScheme() reads prefers-color-scheme through matchMedia and keeps\nfollowing it. Server renders and tests pass the scheme in explicitly.\n---\n src/theme/useColorScheme.ts | 22 ++++++++++++++++++++++\n 1 file changed, 22 insertions(+)\n create mode 100644 src/theme/useColorScheme.ts\n\ndiff --git a/src/theme/useColorScheme.ts b/src/theme/useColorScheme.ts\nnew file mode 100644\nindex 0000000..e496b56\n--- /dev/null\n+++ b/src/theme/useColorScheme.ts\n@@ -0,0 +1,22 @@\n+import { useEffect, useState } from \"react\";\n+\n+export type ColorScheme = \"light\" | \"dark\";\n+\n+const DARK_QUERY = \"(prefers-color-scheme: dark)\";\n+\n+/**\n+ * The system color scheme, kept live. `initial` is what the server render and\n+ * the first client frame use, before matchMedia can be read.\n+ */\n+export function useColorScheme(initial: ColorScheme = \"light\"): ColorScheme {\n+  const [scheme, setScheme] = useState<ColorScheme>(initial);\n+  useEffect(() => {\n+    if (typeof window === \"undefined\" || !window.matchMedia) return;\n+    const media = window.matchMedia(DARK_QUERY);\n+    const update = () => setScheme(media.matches ? \"dark\" : \"light\");\n+    update();\n+    media.addEventListener(\"change\", update);\n+    return () => media.removeEventListener(\"change\", update);\n+  }, []);\n+  return scheme;\n+}\n",
