        "file": "0002-Add-a-dark-palette-and-theme-context.patch",
        "patch": "From 9740fbd4316752734666c3e6f753d2b2095da058 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:21:33 -0700\nSubject: [PATCH 2/4] Add a dark palette and theme context\n\ntokens.ts gains a dark palette and palettes by name. ThemeContext.tsx\nholds the active theme (light by default), usePalette() for components\nthat color inline, and resolveTheme(): a saved choice wins, otherwise\nthe system setting. theme.css switches its variables under\n:root[data-theme=\"dark\"].\n---\n src/theme/ThemeContext.tsx | 25 +++++++++++++++++++++++++\n src/theme/theme.css        | 13 ++++++++++++-\n src/theme/tokens.ts        | 26 ++++++++++++++++++++++----\n 3 files changed, 59 insertions(+), 5 deletions(-)\n create mode 100644 src/theme/ThemeContext.tsx\n\ndiff --git a/src/theme/ThemeContext.tsx b/src/theme/ThemeContext.tsx\nnew file mode 100644\nindex 0000000..15db8ef\n--- /dev/null\n+++ b/src/theme/ThemeContext.tsx\n@@ -0,0 +1,25 @@\n+import { createContext, useContext } from \"react\";\n+import { palettes, type Palette, type ThemeName } from \"./tokens\";\n+\n+/** localStorage key for the reader's explicit choice. */\n+export const THEME_STORAGE_KEY = \"riverlevels-theme\";\n+\n+const ThemeContext = createContext<ThemeName>(\"light\");\n+\n+/** Provides the active theme to everything below it. Defaults to light. */\n+export const ThemeProvider = ThemeContext.Provider;\n+\n+export function useTheme(): ThemeName {\n+  return useContext(ThemeContext);\n+}\n+\n+/** The palette for the active theme, for components that set colors inline. */\n+export function usePalette(): Palette {\n+  return palettes[useContext(ThemeContext)];\n+}\n+\n+/** A saved, valid choice wins; otherwise follow the system setting. */\n+export function resolveTheme(saved: string | null, systemPrefersDark: boolean): ThemeName {\n+  if (saved === \"light\" || saved === \"dark\") return saved;\n+  return systemPrefersDark ? \"dark\" : \"light\";\n+}\ndiff --git a/src/theme/theme.css b/src/theme/theme.css\nindex 355a9aa..4c1e129 100644\n--- a/src/theme/theme.css\n+++ b/src/theme/theme.css\n@@ -1,4 +1,6 @@\n-/* Light theme. Keep these values in sync with tokens.ts. */\n+/* Light theme, and dark when <html data-theme=\"dark\">. The app sets the attribute\n+   from the reader's choice or the system setting.\n+   Keep these values in sync with `light` and `dark` in tokens.ts. */\n :root {\n   --rl-bg: #f5f5f4;\n   --rl-surface: #ffffff;\n@@ -11,6 +13,15 @@\n   color-scheme: light;\n }\n \n+:root[data-theme=\"dark\"] {\n+  --rl-bg: #0c0a09;\n+  --rl-surface: #1c1917;\n+  --rl-ink: #fafaf9;\n+  --rl-muted: #a8a29e;\n+  --rl-line: #292524;\n+  color-scheme: dark;\n+}\n+\n * {\n   box-sizing: border-box;\n }\ndiff --git a/src/theme/tokens.ts b/src/theme/tokens.ts\nindex b374b0e..669e098 100644\n--- a/src/theme/tokens.ts\n+++ b/src/theme/tokens.ts\n@@ -1,6 +1,9 @@\n-// The light palette. theme.css mirrors these values as CSS custom properties for\n-// the page chrome; the Gauge reads them here because its bar color depends on the\n-// reading (alert or not) and its track is a tint of that color, both set inline.\n+// Palettes. theme.css mirrors these values as CSS custom properties for the page\n+// chrome (light on :root, dark on :root[data-theme=\"dark\"]); the Gauge reads them\n+// here because its bar color depends on the reading (alert or not) and its track\n+// is a tint of that color, both set inline.\n+\n+export type ThemeName = \"light\" | \"dark\";\n \n export interface Palette {\n   bg: string;\n@@ -12,7 +15,7 @@ export interface Palette {\n   alert: string;\n }\n \n-export const palette: Palette = {\n+export const light: Palette = {\n   bg: \"#f5f5f4\",\n   surface: \"#ffffff\",\n   ink: \"#1c1917\",\n@@ -21,3 +24,18 @@ export const palette: Palette = {\n   bar: \"#0d9488\",\n   alert: \"#c2410c\",\n };\n+\n+export const dark: Palette = {\n+  bg: \"#0c0a09\",\n+  surface: \"#1c1917\",\n+  ink: \"#fafaf9\",\n+  muted: \"#a8a29e\",\n+  line: \"#292524\",\n+  bar: \"#2dd4bf\",\n+  alert: \"#fb923c\",\n+};\n+\n+export const palettes: Record<ThemeName, Palette> = { light, dark };\n+\n+/** The light palette, under its original name. */\n+export const palette = light;\n",
