        "file": "0003-Color-the-gauge-from-the-active-theme.patch",
        "patch": "From c415141fcf7296ff28161eeca61ecdc7c02a9c6c Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:21:44 -0700\nSubject: [PATCH 3/4] Color the gauge from the active theme\n\nGauge read the light palette directly, so it stayed light on a dark page.\nIt now takes the palette from ThemeContext. Outside a provider it is\nstill light, so existing renders and tests are unchanged.\n---\n src/components/Gauge.tsx | 3 ++-\n 1 file changed, 2 insertions(+), 1 deletion(-)\n\ndiff --git a/src/components/Gauge.tsx b/src/components/Gauge.tsx\nindex e5a6e6b..8bf5eee 100644\n--- a/src/components/Gauge.tsx\n+++ b/src/components/Gauge.tsx\n@@ -1,5 +1,5 @@\n import { useState } from \"react\";\n-import { palette } from \"../theme/tokens\";\n+import { usePalette } from \"../theme/ThemeContext\";\n import type { GaugeKind } from \"../types\";\n \n export interface GaugeProps {\n@@ -16,6 +16,7 @@ export interface GaugeProps {\n }\n \n export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"us\" }: GaugeProps) {\n+  const palette = usePalette();\n   const [units, setUnits] = useState(defaultUnits);\n   const metric = units === \"metric\";\n \n",
