        "file": "0004-Add-a-dark-mode-toggle-that-starts-from-the-system-s.patch",
        "patch": "From 440eebbf9025a00568a282ca2062cf7aace3d9a2 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:22:46 -0700\nSubject: [PATCH 4/4] Add a dark mode toggle that starts from the system\n setting\n\nApp resolves the theme in the browser (saved choice, else\nprefers-color-scheme, followed live until the reader chooses), provides\nit to the gauges, mirrors it on <html data-theme> for the CSS, and saves\nan explicit choice in localStorage. ThemeToggle is a pressed/unpressed\n\"Dark mode\" button in the header. All tests pass.\n---\n src/App.tsx               | 85 +++++++++++++++++++++++++++++----------\n src/theme/ThemeToggle.tsx | 22 ++++++++++\n src/theme/theme.css       | 27 +++++++++++++\n 3 files changed, 113 insertions(+), 21 deletions(-)\n create mode 100644 src/theme/ThemeToggle.tsx\n\ndiff --git a/src/App.tsx b/src/App.tsx\nindex fcae32a..646c865 100644\n--- a/src/App.tsx\n+++ b/src/App.tsx\n@@ -1,5 +1,8 @@\n import { useEffect, useState } from \"react\";\n import { RiverCard } from \"./components/RiverCard\";\n+import { THEME_STORAGE_KEY, ThemeProvider, resolveTheme } from \"./theme/ThemeContext\";\n+import { ThemeToggle } from \"./theme/ThemeToggle\";\n+import type { ThemeName } from \"./theme/tokens\";\n import type { LevelsResponse, River } from \"./types\";\n \n /** The dashboard refreshes every 30 s: one request per open tab, well under any limit. */\n@@ -8,11 +11,22 @@ export const REFRESH_MS = 30_000;\n export interface AppProps {\n   /** Rendered immediately; the dashboard still refreshes from /api/levels. */\n   initialRivers?: River[];\n+  /** Fixes the theme (server render, tests). Otherwise it is resolved in the browser. */\n+  initialTheme?: ThemeName;\n }\n \n-export function App({ initialRivers }: AppProps) {\n+function savedTheme(): string | null {\n+  try {\n+    return localStorage.getItem(THEME_STORAGE_KEY);\n+  } catch {\n+    return null;\n+  }\n+}\n+\n+export function App({ initialRivers, initialTheme }: AppProps) {\n   const [rivers, setRivers] = useState<River[] | null>(initialRivers ?? null);\n   const [error, setError] = useState<string | null>(null);\n+  const [theme, setTheme] = useState<ThemeName>(initialTheme ?? \"light\");\n \n   useEffect(() => {\n     let alive = true;\n@@ -36,26 +50,55 @@ export function App({ initialRivers }: AppProps) {\n     };\n   }, []);\n \n+  // The reader's saved choice, else the system setting, which we keep following\n+  // until the reader picks a theme themselves.\n+  useEffect(() => {\n+    if (initialTheme) return;\n+    const media = window.matchMedia(\"(prefers-color-scheme: dark)\");\n+    setTheme(resolveTheme(savedTheme(), media.matches));\n+    const follow = (event: MediaQueryListEvent) => {\n+      if (savedTheme() === null) setTheme(event.matches ? \"dark\" : \"light\");\n+    };\n+    media.addEventListener(\"change\", follow);\n+    return () => media.removeEventListener(\"change\", follow);\n+  }, [initialTheme]);\n+\n+  useEffect(() => {\n+    document.documentElement.dataset.theme = theme;\n+  }, [theme]);\n+\n+  const chooseTheme = (next: ThemeName) => {\n+    setTheme(next);\n+    try {\n+      localStorage.setItem(THEME_STORAGE_KEY, next);\n+    } catch {\n+      // Storage disabled or private mode: the choice lasts for this visit.\n+    }\n+  };\n+\n   return (\n-    <main className=\"app\">\n-      <header className=\"app-header\">\n-        <h1>River levels</h1>\n-        <p className=\"app-subtitle\">Stage, flow and water temperature</p>\n-      </header>\n-      {error && (\n-        <p className=\"app-error\" role=\"alert\">\n-          {`Couldn’t refresh the gauges: ${error}`}\n-        </p>\n-      )}\n-      {rivers === null ? (\n-        <p className=\"app-loading\">Loading gauges…</p>\n-      ) : (\n-        <section className=\"river-grid\" aria-label=\"Rivers\">\n-          {rivers.map((river) => (\n-            <RiverCard key={river.id} river={river} />\n-          ))}\n-        </section>\n-      )}\n-    </main>\n+    <ThemeProvider value={theme}>\n+      <main className=\"app\" data-theme={theme}>\n+        <header className=\"app-header\">\n+          <h1>River levels</h1>\n+          <p className=\"app-subtitle\">Stage, flow and water temperature</p>\n+          <ThemeToggle theme={theme} onChange={chooseTheme} />\n+        </header>\n+        {error && (\n+          <p className=\"app-error\" role=\"alert\">\n+            {`Couldn’t refresh the gauges: ${error}`}\n+          </p>\n+        )}\n+        {rivers === null ? (\n+          <p className=\"app-loading\">Loading gauges…</p>\n+        ) : (\n+          <section className=\"river-grid\" aria-label=\"Rivers\">\n+            {rivers.map((river) => (\n+              <RiverCard key={river.id} river={river} />\n+            ))}\n+          </section>\n+        )}\n+      </main>\n+    </ThemeProvider>\n   );\n }\ndiff --git a/src/theme/ThemeToggle.tsx b/src/theme/ThemeToggle.tsx\nnew file mode 100644\nindex 0000000..58e16a1\n--- /dev/null\n+++ b/src/theme/ThemeToggle.tsx\n@@ -0,0 +1,22 @@\n+import type { ThemeName } from \"./tokens\";\n+\n+export interface ThemeToggleProps {\n+  theme: ThemeName;\n+  onChange: (theme: ThemeName) => void;\n+}\n+\n+/** A pressed/unpressed \"Dark mode\" button. */\n+export function ThemeToggle({ theme, onChange }: ThemeToggleProps) {\n+  const isDark = theme === \"dark\";\n+  return (\n+    <button\n+      type=\"button\"\n+      className=\"theme-toggle\"\n+      aria-pressed={isDark}\n+      onClick={() => onChange(isDark ? \"light\" : \"dark\")}\n+    >\n+      <span className=\"theme-toggle-dot\" aria-hidden=\"true\" />\n+      Dark mode\n+    </button>\n+  );\n+}\ndiff --git a/src/theme/theme.css b/src/theme/theme.css\nindex 4c1e129..949dd75 100644\n--- a/src/theme/theme.css\n+++ b/src/theme/theme.css\n@@ -59,6 +59,33 @@ body {\n   letter-spacing: -0.01em;\n }\n \n+.theme-toggle {\n+  display: inline-flex;\n+  align-items: center;\n+  gap: 8px;\n+  margin-left: auto;\n+  padding: 6px 12px;\n+  border: 1px solid var(--rl-line);\n+  border-radius: 999px;\n+  background: var(--rl-surface);\n+  color: var(--rl-ink);\n+  font: inherit;\n+  font-size: 13px;\n+  cursor: pointer;\n+}\n+\n+.theme-toggle-dot {\n+  width: 10px;\n+  height: 10px;\n+  border-radius: 50%;\n+  border: 1px solid var(--rl-muted);\n+}\n+\n+.theme-toggle[aria-pressed=\"true\"] .theme-toggle-dot {\n+  background: var(--rl-ink);\n+  border-color: var(--rl-ink);\n+}\n+\n .app-subtitle,\n .app-loading {\n   margin: 0;\n",
