        "file": "0001-Add-a-Durable-Object-rate-limiter-and-cache-helper.patch",
        "patch": "From 2a76194db1554fe38d0620a65b5cda9d72728efb Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:38:23 -0700\nSubject: [PATCH 1/2] Add a Durable Object rate limiter and cache helper\n\nsrc/api/rateLimit.ts holds all of it: a RateLimiter Durable Object (one\ntoken bucket per caller, 10 per second), the rateLimit middleware that\nasks it, and cache(seconds). Bound as RATE_LIMITER in wrangler.jsonc and\nexported from the Worker. Not wired into the API yet.\n---\n src/api/rateLimit.ts | 44 ++++++++++++++++++++++++++++++++++++++++++++\n src/worker.ts        |  5 ++++-\n wrangler.jsonc       |  4 +++-\n 3 files changed, 51 insertions(+), 2 deletions(-)\n create mode 100644 src/api/rateLimit.ts\n\ndiff --git a/src/api/rateLimit.ts b/src/api/rateLimit.ts\nnew file mode 100644\nindex 0000000..c6a1260\n--- /dev/null\n+++ b/src/api/rateLimit.ts\n@@ -0,0 +1,44 @@\n+import type { MiddlewareHandler } from \"hono\";\n+\n+const LIMIT = 10; // req/s per token, also the burst size\n+\n+interface Namespace {\n+  idFromName(name: string): unknown;\n+  get(id: unknown): { fetch(url: string): Promise<Response> };\n+}\n+\n+export type RateLimitEnv = { Bindings: { RATE_LIMITER?: Namespace } };\n+\n+/** Durable Object: one token bucket per caller, refilled at LIMIT tokens per second. */\n+export class RateLimiter {\n+  private tokens = LIMIT;\n+  private last = Date.now();\n+\n+  async fetch(): Promise<Response> {\n+    const now = Date.now();\n+    this.tokens = Math.min(LIMIT, this.tokens + ((now - this.last) / 1000) * LIMIT);\n+    this.last = now;\n+    const ok = this.tokens >= 1;\n+    if (ok) this.tokens -= 1;\n+    return new Response(ok ? \"ok\" : \"limited\", { status: ok ? 200 : 429 });\n+  }\n+}\n+\n+/** 429 `{ error: \"rate_limited\", retryAfter: 1 }` once a caller's bucket is empty. */\n+export const rateLimit: MiddlewareHandler<RateLimitEnv> = async (c, next) => {\n+  const limiter = c.env?.RATE_LIMITER;\n+  if (limiter) {\n+    const key = c.req.header(\"authorization\") ?? c.req.header(\"cf-connecting-ip\") ?? \"anonymous\";\n+    const res = await limiter.get(limiter.idFromName(key)).fetch(\"https://limiter/\");\n+    if (res.status === 429) return c.json({ error: \"rate_limited\", retryAfter: 1 }, 429);\n+  }\n+  await next();\n+};\n+\n+/** Cache-Control: max-age=<seconds> on successful responses. */\n+export const cache =\n+  (seconds: number): MiddlewareHandler =>\n+  async (c, next) => {\n+    await next();\n+    if (c.res.status === 200) c.header(\"Cache-Control\", `max-age=${seconds}`);\n+  };\ndiff --git a/src/worker.ts b/src/worker.ts\nindex f2e7fc6..9d57754 100644\n--- a/src/worker.ts\n+++ b/src/worker.ts\n@@ -1,9 +1,12 @@\n import { Hono } from \"hono\";\n import { api } from \"./api\";\n+import type { RateLimitEnv } from \"./api/rateLimit\";\n+\n+export { RateLimiter } from \"./api/rateLimit\";\n \n // The Worker answers /api/*. Everything else is the built UI in dist/, served as\n // static assets (see `assets` in wrangler.jsonc).\n-export const app = new Hono();\n+export const app = new Hono<RateLimitEnv>();\n \n app.route(\"/api\", api);\n app.notFound((c) => c.json({ error: \"not_found\" }, 404));\ndiff --git a/wrangler.jsonc b/wrangler.jsonc\nindex ca17397..72a825d 100644\n--- a/wrangler.jsonc\n+++ b/wrangler.jsonc\n@@ -10,5 +10,7 @@\n     \"directory\": \"./dist\",\n     \"not_found_handling\": \"single-page-application\",\n     \"run_worker_first\": [\"/api/*\"]\n-  }\n+  },\n+  \"durable_objects\": { \"bindings\": [{ \"name\": \"RATE_LIMITER\", \"class_name\": \"RateLimiter\" }] },\n+  \"migrations\": [{ \"tag\": \"v1\", \"new_sqlite_classes\": [\"RateLimiter\"] }]\n }\n",
