        "file": "0002-Rate-limit-api-and-cache-levels-for-60-seconds.patch",
        "patch": "From eaeb04f83b59da59432e7fe97b3f578b4927d1f9 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:38:55 -0700\nSubject: [PATCH 2/2] Rate-limit /api and cache /levels for 60 seconds\n\nThree lines in the API: rateLimit on every route and cache(60) on\n/levels. Without the binding (pnpm dev, the existing tests) the limiter\nis skipped.\n---\n src/api/index.ts        |  6 ++++--\n test/rate-limit.test.ts | 43 +++++++++++++++++++++++++++++++++++++++++\n 2 files changed, 47 insertions(+), 2 deletions(-)\n create mode 100644 test/rate-limit.test.ts\n\ndiff --git a/src/api/index.ts b/src/api/index.ts\nindex 1dff939..aee7956 100644\n--- a/src/api/index.ts\n+++ b/src/api/index.ts\n@@ -1,7 +1,9 @@\n import { Hono } from \"hono\";\n import { level, levels } from \"./levels\";\n+import { cache, rateLimit, type RateLimitEnv } from \"./rateLimit\";\n \n-export const api = new Hono();\n+export const api = new Hono<RateLimitEnv>();\n \n-api.get(\"/levels\", levels);\n+api.use(\"*\", rateLimit);\n+api.get(\"/levels\", cache(60), levels);\n api.get(\"/levels/:id\", level);\ndiff --git a/test/rate-limit.test.ts b/test/rate-limit.test.ts\nnew file mode 100644\nindex 0000000..0837801\n--- /dev/null\n+++ b/test/rate-limit.test.ts\n@@ -0,0 +1,43 @@\n+import { afterEach, beforeEach, expect, it, vi } from \"vitest\";\n+import { RateLimiter } from \"../src/api/rateLimit\";\n+import { app } from \"../src/worker\";\n+\n+// RATE_LIMITER backed by real RateLimiter objects, one per name.\n+function env() {\n+  const objects = new Map<string, RateLimiter>();\n+  return {\n+    RATE_LIMITER: {\n+      idFromName: (name: string) => name,\n+      get: (id: unknown) => {\n+        const name = String(id);\n+        if (!objects.has(name)) objects.set(name, new RateLimiter());\n+        return objects.get(name)!;\n+      },\n+    },\n+  };\n+}\n+\n+const get = (bindings: ReturnType<typeof env>, token: string) =>\n+  app.request(\"/api/levels\", { headers: { authorization: `Bearer ${token}` } }, bindings);\n+\n+beforeEach(() => {\n+  vi.useFakeTimers({ toFake: [\"Date\"] });\n+  vi.setSystemTime(0);\n+});\n+afterEach(() => vi.useRealTimers());\n+\n+it(\"allows 10 requests per second per token, then answers 429\", async () => {\n+  const bindings = env();\n+  for (let i = 0; i < 10; i++) expect((await get(bindings, \"a\")).status).toBe(200);\n+  const res = await get(bindings, \"a\");\n+  expect(res.status).toBe(429);\n+  expect(await res.json()).toEqual({ error: \"rate_limited\", retryAfter: 1 });\n+  expect((await get(bindings, \"b\")).status).toBe(200);\n+  vi.setSystemTime(1000);\n+  expect((await get(bindings, \"a\")).status).toBe(200);\n+});\n+\n+it(\"caches /levels for 60 seconds\", async () => {\n+  const res = await app.request(\"/api/levels\");\n+  expect(res.headers.get(\"cache-control\")).toBe(\"max-age=60\");\n+});\n",
