        "patch": "From 9588dbba159424ff702c44f7f7e378cd43b36c1d Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:40:30 -0700\nSubject: [PATCH 1/2] Extract useGauge from Gauge\n\nMove the unit state, conversion, formatting and bar math out of the\ncomponent, unchanged, into src/hooks/useGauge.ts. Gauge keeps its props,\nmarkup and colors and reads reading, pct, alert and toggleUnits from the\nhook. No behavior change; the existing tests pass as they are.\n---\n src/components/Gauge.tsx | 29 +++-------------------\n src/hooks/useGauge.ts    | 53 ++++++++++++++++++++++++++++++++++++++++\n 2 files changed, 56 insertions(+), 26 deletions(-)\n create mode 100644 src/hooks/useGauge.ts\n\ndiff --git a/src/components/Gauge.tsx b/src/components/Gauge.tsx\nindex e5a6e6b..92453f2 100644\n--- a/src/components/Gauge.tsx\n+++ b/src/components/Gauge.tsx\n@@ -1,4 +1,4 @@\n-import { useState } from \"react\";\n+import { useGauge } from \"../hooks/useGauge\";\n import { palette } from \"../theme/tokens\";\n import type { GaugeKind } from \"../types\";\n \n@@ -16,30 +16,7 @@ export interface GaugeProps {\n }\n \n export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"us\" }: GaugeProps) {\n-  const [units, setUnits] = useState(defaultUnits);\n-  const metric = units === \"metric\";\n-\n-  let shown = value;\n-  let unit = \"ft\";\n-  if (kind === \"stage\") {\n-    shown = metric ? value * 0.3048 : value;\n-    unit = metric ? \"m\" : \"ft\";\n-  } else if (kind === \"flow\") {\n-    shown = metric ? value * 0.0283168 : value;\n-    unit = metric ? \"m³/s\" : \"cfs\";\n-  } else {\n-    shown = metric ? ((value - 32) * 5) / 9 : value;\n-    unit = metric ? \"°C\" : \"°F\";\n-  }\n-\n-  let reading: string;\n-  if (kind === \"temp\") reading = `${Math.round(shown)}${unit}`;\n-  else if (kind === \"flow\" && !metric) reading = `${Math.round(shown).toLocaleString(\"en-US\")} ${unit}`;\n-  else reading = `${shown.toFixed(1)} ${unit}`;\n-\n-  const span = max - min;\n-  const pct = span > 0 ? Math.min(100, Math.max(0, ((value - min) / span) * 100)) : 0;\n-  const alert = alertAt !== undefined && value >= alertAt;\n+  const { reading, pct, alert, metric, toggleUnits } = useGauge({ kind, value, min, max, alertAt, defaultUnits });\n   const barColor = alert ? palette.alert : palette.bar;\n \n   return (\n@@ -63,7 +40,7 @@ export function Gauge({ kind, label, value, min, max, alertAt, defaultUnits = \"u\n         type=\"button\"\n         className=\"gauge-value\"\n         title={metric ? \"Show US units\" : \"Show metric units\"}\n-        onClick={() => setUnits(metric ? \"us\" : \"metric\")}\n+        onClick={toggleUnits}\n         style={{ color: palette.ink }}\n       >\n         {reading}\ndiff --git a/src/hooks/useGauge.ts b/src/hooks/useGauge.ts\nnew file mode 100644\nindex 0000000..7e78200\n--- /dev/null\n+++ b/src/hooks/useGauge.ts\n@@ -0,0 +1,53 @@\n+import { useState } from \"react\";\n+import type { GaugeKind } from \"../types\";\n+\n+export interface UseGaugeOptions {\n+  kind: GaugeKind;\n+  /** Reading in US units: feet (stage), cubic feet per second (flow), °F (temp). */\n+  value: number;\n+  min: number;\n+  max: number;\n+  alertAt?: number;\n+  defaultUnits?: \"us\" | \"metric\";\n+}\n+\n+export interface GaugeState {\n+  /** The reading in the current units, e.g. \"6.2 ft\" or \"1.9 m\". */\n+  reading: string;\n+  /** Bar fill as a percentage of the range, clamped to 0–100. */\n+  pct: number;\n+  /** At or above the alert threshold. */\n+  alert: boolean;\n+  metric: boolean;\n+  toggleUnits: () => void;\n+}\n+\n+/** Unit state, conversion, formatting and bar math for a Gauge. */\n+export function useGauge({ kind, value, min, max, alertAt, defaultUnits = \"us\" }: UseGaugeOptions): GaugeState {\n+  const [units, setUnits] = useState(defaultUnits);\n+  const metric = units === \"metric\";\n+\n+  let shown = value;\n+  let unit = \"ft\";\n+  if (kind === \"stage\") {\n+    shown = metric ? value * 0.3048 : value;\n+    unit = metric ? \"m\" : \"ft\";\n+  } else if (kind === \"flow\") {\n+    shown = metric ? value * 0.0283168 : value;\n+    unit = metric ? \"m³/s\" : \"cfs\";\n+  } else {\n+    shown = metric ? ((value - 32) * 5) / 9 : value;\n+    unit = metric ? \"°C\" : \"°F\";\n+  }\n+\n+  let reading: string;\n+  if (kind === \"temp\") reading = `${Math.round(shown)}${unit}`;\n+  else if (kind === \"flow\" && !metric) reading = `${Math.round(shown).toLocaleString(\"en-US\")} ${unit}`;\n+  else reading = `${shown.toFixed(1)} ${unit}`;\n+\n+  const span = max - min;\n+  const pct = span > 0 ? Math.min(100, Math.max(0, ((value - min) / span) * 100)) : 0;\n+  const alert = alertAt !== undefined && value >= alertAt;\n+\n+  return { reading, pct, alert, metric, toggleUnits: () => setUnits(metric ? \"us\" : \"metric\") };\n+}\n",
