        "file": "0002-Test-useGauge-directly.patch",
        "patch": "From 1510c3e20768863e214e3bc90741e4ff76041253 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:40:59 -0700\nSubject: [PATCH 2/2] Test useGauge directly\n\nRun the hook in a server render through a small probe component and\ncheck its formatting, metric start, fill and alert flag.\n---\n test/useGauge.test.tsx | 33 +++++++++++++++++++++++++++++++++\n 1 file changed, 33 insertions(+)\n create mode 100644 test/useGauge.test.tsx\n\ndiff --git a/test/useGauge.test.tsx b/test/useGauge.test.tsx\nnew file mode 100644\nindex 0000000..a950c51\n--- /dev/null\n+++ b/test/useGauge.test.tsx\n@@ -0,0 +1,33 @@\n+import { renderToString } from \"react-dom/server\";\n+import { describe, expect, it } from \"vitest\";\n+import { useGauge, type GaugeState, type UseGaugeOptions } from \"../src/hooks/useGauge\";\n+\n+/** Run the hook in a server render and hand back what it returned. */\n+function run(options: UseGaugeOptions): Omit<GaugeState, \"toggleUnits\"> {\n+  let state: GaugeState | undefined;\n+  function Probe() {\n+    state = useGauge(options);\n+    return null;\n+  }\n+  renderToString(<Probe />);\n+  const { toggleUnits: _toggle, ...rest } = state!;\n+  return rest;\n+}\n+\n+describe(\"useGauge\", () => {\n+  it(\"formats each kind in US units\", () => {\n+    expect(run({ kind: \"stage\", value: 6.2, min: 0, max: 10 }).reading).toBe(\"6.2 ft\");\n+    expect(run({ kind: \"flow\", value: 4810, min: 0, max: 10000 }).reading).toBe(\"4,810 cfs\");\n+    expect(run({ kind: \"temp\", value: 51, min: 32, max: 86 }).reading).toBe(\"51°F\");\n+  });\n+\n+  it(\"starts in metric when asked\", () => {\n+    const stage = run({ kind: \"stage\", value: 6.2, min: 0, max: 10, defaultUnits: \"metric\" });\n+    expect(stage).toMatchObject({ reading: \"1.9 m\", metric: true });\n+  });\n+\n+  it(\"returns the clamped fill and the alert flag\", () => {\n+    expect(run({ kind: \"stage\", value: 6.2, min: 0, max: 10, alertAt: 9 })).toMatchObject({ pct: 62, alert: false });\n+    expect(run({ kind: \"stage\", value: 12, min: 0, max: 10, alertAt: 9 })).toMatchObject({ pct: 100, alert: true });\n+  });\n+});\n",
