        "file": "0003-Test-useGauge-s-scales-helpers-and-prop-getters.patch",
        "patch": "From 6c553d97b6ff482fd136afd83fcc4dd3bd3439f7 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:45:50 -0700\nSubject: [PATCH 3/3] Test useGauge's scales, helpers and prop getters\n\nCover the SCALES table, formatting (now with thousands grouping in metric\ntoo), the fill clamp, the hook's output in both unit systems, and the\nmeter and toggle props it hands out.\n---\n test/useGauge.test.tsx | 50 ++++++++++++++++++++++++++++++++++++++++++\n 1 file changed, 50 insertions(+)\n create mode 100644 test/useGauge.test.tsx\n\ndiff --git a/test/useGauge.test.tsx b/test/useGauge.test.tsx\nnew file mode 100644\nindex 0000000..3a3d615\n--- /dev/null\n+++ b/test/useGauge.test.tsx\n@@ -0,0 +1,50 @@\n+import { renderToString } from \"react-dom/server\";\n+import { describe, expect, it } from \"vitest\";\n+import { SCALES, fillPercent, formatReading, useGauge, type UseGauge } from \"../src/hooks/useGauge\";\n+import type { GaugeKind, Reading } from \"../src/types\";\n+\n+const snakeStage: Reading = { value: 6.2, unit: \"ft\", min: 0, max: 10, alertAt: 9 };\n+\n+function run(kind: GaugeKind, reading: Reading, units?: \"us\" | \"metric\"): UseGauge {\n+  let state: UseGauge | undefined;\n+  function Probe() {\n+    state = useGauge(kind, \"Gauge\", reading, units);\n+    return null;\n+  }\n+  renderToString(<Probe />);\n+  return state!;\n+}\n+\n+describe(\"useGauge helpers\", () => {\n+  it(\"has a scale for every kind in both unit systems\", () => {\n+    for (const kind of [\"stage\", \"flow\", \"temp\"] as const) {\n+      expect(Object.keys(SCALES[kind]).sort()).toEqual([\"metric\", \"us\"]);\n+    }\n+  });\n+\n+  it(\"formats readings, grouping thousands in both systems\", () => {\n+    expect(formatReading(\"flow\", 4810, \"us\")).toBe(\"4,810 cfs\");\n+    expect(formatReading(\"flow\", 40000, \"metric\")).toBe(\"1,132.7 m³/s\");\n+    expect(formatReading(\"temp\", 14, \"metric\")).toBe(\"-10°C\");\n+  });\n+\n+  it(\"clamps the fill to the gauge's range\", () => {\n+    expect(fillPercent(snakeStage)).toBeCloseTo(62);\n+    expect(fillPercent({ ...snakeStage, value: -3 })).toBe(0);\n+    expect(fillPercent({ ...snakeStage, min: 2, max: 2 })).toBe(0);\n+  });\n+});\n+\n+describe(\"useGauge\", () => {\n+  it(\"returns text, fill and alert for the default units\", () => {\n+    expect(run(\"stage\", snakeStage)).toMatchObject({ units: \"us\", text: \"6.2 ft\", alert: false });\n+    expect(run(\"stage\", { ...snakeStage, value: 9.1 }, \"metric\")).toMatchObject({ units: \"metric\", text: \"2.8 m\", alert: true });\n+  });\n+\n+  it(\"hands out ARIA meter props and a toggle button\", () => {\n+    const gauge = run(\"temp\", { value: 51, unit: \"°F\", min: 32, max: 86 });\n+    expect(gauge.getMeterProps()).toMatchObject({ role: \"meter\", \"aria-valuenow\": 51, \"aria-valuetext\": \"51°F\" });\n+    expect(gauge.getToggleProps()).toMatchObject({ type: \"button\", title: \"Show metric units\" });\n+    expect(gauge.getToggleProps().onClick).toBe(gauge.toggleUnits);\n+  });\n+});\n",
