        "file": "0001-Pin-the-gauge-s-current-behavior.patch",
        "patch": "From 3106f77b55bc76b5c395a29bfd24721823432c8c Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:42:05 -0700\nSubject: [PATCH 1/4] Pin the gauge's current behavior\n\nCharacterization tests for the edges the existing suite doesn't reach:\nungrouped metric flow, sub-zero conversion, fill rounding, the alert\nthreshold's boundary, and the ARIA and title text in both unit systems.\nThey pass against today's Gauge and must keep passing through the\nrefactor.\n---\n test/gauge-behavior.test.tsx | 46 ++++++++++++++++++++++++++++++++++++\n 1 file changed, 46 insertions(+)\n create mode 100644 test/gauge-behavior.test.tsx\n\ndiff --git a/test/gauge-behavior.test.tsx b/test/gauge-behavior.test.tsx\nnew file mode 100644\nindex 0000000..e6f769f\n--- /dev/null\n+++ b/test/gauge-behavior.test.tsx\n@@ -0,0 +1,46 @@\n+// Characterization tests: what Gauge does today, edge cases included, so the\n+// refactor can prove it changed nothing.\n+import { renderToString } from \"react-dom/server\";\n+import { describe, expect, it } from \"vitest\";\n+import { Gauge, type GaugeProps } from \"../src/components/Gauge\";\n+\n+const html = (props: GaugeProps) => renderToString(<Gauge {...props} />);\n+const value = (markup: string) => /class=\"gauge-value\"[^>]*>([^<]*)<\\/button>/.exec(markup)?.[1];\n+const width = (markup: string) => /width:(\\d+)%/.exec(markup)?.[1];\n+\n+describe(\"Gauge today\", () => {\n+  it(\"keeps metric flow ungrouped with one decimal\", () => {\n+    expect(value(html({ kind: \"flow\", label: \"Flow\", value: 40000, min: 0, max: 40000, defaultUnits: \"metric\" }))).toBe(\n+      \"1132.7 m³/s\",\n+    );\n+  });\n+\n+  it(\"converts freezing and sub-zero temperatures\", () => {\n+    expect(value(html({ kind: \"temp\", label: \"Temp\", value: 32, min: 0, max: 100, defaultUnits: \"metric\" }))).toBe(\"0°C\");\n+    expect(value(html({ kind: \"temp\", label: \"Temp\", value: 14, min: 0, max: 100, defaultUnits: \"metric\" }))).toBe(\"-10°C\");\n+  });\n+\n+  it(\"rounds the bar to whole percent\", () => {\n+    expect(width(html({ kind: \"stage\", label: \"Stage\", value: 3.33, min: 0, max: 10 }))).toBe(\"33\");\n+    expect(width(html({ kind: \"stage\", label: \"Stage\", value: 3.36, min: 0, max: 10 }))).toBe(\"34\");\n+  });\n+\n+  it(\"alerts at the threshold, not below it, and never without one\", () => {\n+    const at = { kind: \"stage\", label: \"Stage\", min: 0, max: 10 } as const;\n+    expect(html({ ...at, value: 9, alertAt: 9 })).toContain('data-alert=\"true\"');\n+    expect(html({ ...at, value: 8.99, alertAt: 9 })).not.toContain(\"data-alert\");\n+    expect(html({ ...at, value: 10 })).not.toContain(\"data-alert\");\n+  });\n+\n+  it(\"describes itself to assistive tech in the units shown\", () => {\n+    const us = html({ kind: \"stage\", label: \"Stage\", value: 6.2, min: 0, max: 10 });\n+    expect(us).toContain('aria-label=\"Stage\"');\n+    expect(us).toContain('aria-valuenow=\"6.2\"');\n+    expect(us).toContain('aria-valuetext=\"6.2 ft\"');\n+    expect(us).toContain('title=\"Show metric units\"');\n+    const metric = html({ kind: \"stage\", label: \"Stage\", value: 6.2, min: 0, max: 10, defaultUnits: \"metric\" });\n+    expect(metric).toContain('aria-valuenow=\"6.2\"');\n+    expect(metric).toContain('aria-valuetext=\"1.9 m\"');\n+    expect(metric).toContain('title=\"Show US units\"');\n+  });\n+});\n",
