        "file": "0002-Specify-useGauge-in-failing-tests.patch",
        "patch": "From 3ab24ab27810dfe46034212430cbd2142d4fdb55 Mon Sep 17 00:00:00 2001\nFrom: Headwaters <agents@braid.drp.icu>\nDate: Mon, 12 Oct 2026 13:42:27 -0700\nSubject: [PATCH 2/4] Specify useGauge in failing tests\n\nThe extracted API, written down first: gaugeReading(input, units) is a\npure function returning reading, pct and alert, and useGauge adds the\nunits state and a toggle on top of it. Fails until src/hooks/useGauge.ts\nexists.\n---\n test/useGauge.test.tsx | 46 ++++++++++++++++++++++++++++++++++++++++++\n 1 file changed, 46 insertions(+)\n create mode 100644 test/useGauge.test.tsx\n\ndiff --git a/test/useGauge.test.tsx b/test/useGauge.test.tsx\nnew file mode 100644\nindex 0000000..a01c4f1\n--- /dev/null\n+++ b/test/useGauge.test.tsx\n@@ -0,0 +1,46 @@\n+import { renderToString } from \"react-dom/server\";\n+import { describe, expect, it } from \"vitest\";\n+import { gaugeReading, useGauge, type GaugeInput, type UseGauge } from \"../src/hooks/useGauge\";\n+\n+const stage: GaugeInput = { kind: \"stage\", value: 6.2, min: 0, max: 10, alertAt: 9 };\n+const flow: GaugeInput = { kind: \"flow\", value: 4810, min: 0, max: 10000 };\n+const temp: GaugeInput = { kind: \"temp\", value: 51, min: 32, max: 86 };\n+\n+describe(\"gaugeReading\", () => {\n+  it(\"formats every kind in both unit systems\", () => {\n+    expect([stage, flow, temp].map((g) => gaugeReading(g, \"us\").reading)).toEqual([\"6.2 ft\", \"4,810 cfs\", \"51°F\"]);\n+    expect([stage, flow, temp].map((g) => gaugeReading(g, \"metric\").reading)).toEqual([\"1.9 m\", \"136.2 m³/s\", \"11°C\"]);\n+  });\n+\n+  it(\"returns the clamped fill and the alert flag\", () => {\n+    expect(gaugeReading(stage, \"us\")).toMatchObject({ pct: 62, alert: false });\n+    expect(gaugeReading({ ...stage, value: 11 }, \"us\")).toMatchObject({ pct: 100, alert: true });\n+    expect(gaugeReading({ ...stage, min: 4, max: 4 }, \"us\").pct).toBe(0);\n+  });\n+});\n+\n+describe(\"useGauge\", () => {\n+  /** Run the hook in a server render and hand back what it returned. */\n+  function run(input: GaugeInput & { defaultUnits?: \"us\" | \"metric\" }): UseGauge {\n+    let state: UseGauge | undefined;\n+    function Probe() {\n+      state = useGauge(input);\n+      return null;\n+    }\n+    renderToString(<Probe />);\n+    return state!;\n+  }\n+\n+  it(\"starts in the default units and matches gaugeReading\", () => {\n+    const us = run(stage);\n+    expect(us.units).toBe(\"us\");\n+    expect(us).toMatchObject(gaugeReading(stage, \"us\"));\n+    const metric = run({ ...stage, defaultUnits: \"metric\" });\n+    expect(metric.units).toBe(\"metric\");\n+    expect(metric).toMatchObject(gaugeReading(stage, \"metric\"));\n+  });\n+\n+  it(\"offers a units toggle\", () => {\n+    expect(typeof run(flow).toggleUnits).toBe(\"function\");\n+  });\n+});\n",
