      "src/components/RiverCard.tsx": "import type { ColorScheme } from \"../theme/useColorScheme\";\nimport type { River } from \"../types\";\nimport { Gauge } from \"./Gauge\";\n\nconst CARD_COLORS = {\n  light: { background: \"#ffffff\", border: \"#e7e5e4\", title: \"#1c1917\", meta: \"#78716c\" },\n  dark: { background: \"#1c1917\", border: \"#292524\", title: \"#fafaf9\", meta: \"#a8a29e\" },\n} as const;\n\n/** \"2026-10-12T14:00:00Z\" → \"14:00 UTC\". UTC on purpose: gauges report in UTC. */\nfunction formatUpdated(iso: string): string {\n  const date = new Date(iso);\n  return Number.isNaN(date.getTime()) ? \"unknown\" : `${date.toISOString().slice(11, 16)} UTC`;\n}\n\nexport interface RiverCardProps {\n  river: River;\n  scheme?: ColorScheme;\n}\n\nexport function RiverCard({ river, scheme = \"light\" }: RiverCardProps) {\n  const headingId = `river-${river.id}`;\n  const colors = CARD_COLORS[scheme];\n  return (\n    <article\n      className=\"river-card\"\n      aria-labelledby={headingId}\n      style={{ background: colors.background, borderColor: colors.border }}\n    >\n      <header className=\"river-card-header\">\n        <h2 id={headingId} style={{ color: colors.title }}>\n          {river.name}\n        </h2>\n        <span className=\"river-site\" style={{ color: colors.meta }}>\n          {river.site}\n        </span>\n      </header>\n      <div className=\"river-gauges\">\n        <Gauge kind=\"stage\" label=\"Stage\" scheme={scheme} reading={river.stage} />\n        <Gauge kind=\"flow\" label=\"Flow\" scheme={scheme} reading={river.flow} />\n        <Gauge kind=\"temp\" label=\"Temp\" scheme={scheme} reading={river.temp} />\n      </div>\n      <footer className=\"river-updated\" style={{ color: colors.meta }}>\n        {`Updated ${formatUpdated(river.updatedAt)}`}\n      </footer>\n    </article>\n  );\n}\n",
      "test/dark-mode.test.tsx": "import { renderToString } from \"react-dom/server\";\nimport { describe, expect, it } from \"vitest\";\nimport { App } from \"../src/App\";\nimport { RIVERS } from \"../src/api/data\";\nimport { GAUGE_COLORS, Gauge } from \"../src/components/Gauge\";\nimport { RiverCard } from \"../src/components/RiverCard\";\n\nconst snake = RIVERS.find((r) => r.id === \"snake-moose\")!;\n\ndescribe(\"dark mode\", () => {\n  it(\"draws the gauge in dark colors\", () => {\n    const html = renderToString(<Gauge kind=\"flow\" label=\"Flow\" scheme=\"dark\" reading={snake.flow} />);\n    expect(html).toContain(`background:${GAUGE_COLORS.dark.bar}`);\n    expect(html).toContain(`background:${GAUGE_COLORS.dark.track}`);\n    expect(html).toContain(`color:${GAUGE_COLORS.dark.value}`);\n    expect(html).toContain(\">4,810 cfs</button>\");\n  });\n\n  it(\"keeps the alert visible in the dark\", () => {\n    const html = renderToString(\n      <Gauge kind=\"stage\" label=\"Stage\" scheme=\"dark\" reading={{ ...snake.stage, value: 9.4 }} />,\n    );\n    expect(html).toContain('data-alert=\"true\"');\n    expect(html).toContain(`background:${GAUGE_COLORS.dark.alert}`);\n    expect(html).toContain(`background:${GAUGE_COLORS.dark.alertTrack}`);\n  });\n\n  it(\"puts dark cards on a dark page\", () => {\n    const html = renderToString(<App initialRivers={RIVERS} initialScheme=\"dark\" />);\n    expect(html).toContain('data-scheme=\"dark\"');\n    expect(html).toContain(\"background:#0c0a09\");\n    expect(html.split(\"background:#1c1917\").length - 1).toBe(RIVERS.length);\n    expect(html).not.toContain(GAUGE_COLORS.light.bar);\n  });\n\n  it(\"stays light by default\", () => {\n    const html = renderToString(<RiverCard river={snake} />);\n    expect(html).toContain(\"background:#ffffff\");\n    expect(html).toContain(`background:${GAUGE_COLORS.light.bar}`);\n    expect(html).not.toContain(GAUGE_COLORS.dark.bar);\n  });\n});\n",
      "test/gauge.test.tsx": "import { renderToString } from \"react-dom/server\";\nimport { describe, expect, it } from \"vitest\";\nimport { GAUGE_COLORS, Gauge } from \"../src/components/Gauge\";\nimport type { GaugeKind } from \"../src/types\";\n\n/** Flat fixtures, so each case can override one field; html() builds the Reading. */\ninterface Fixture {\n  kind: GaugeKind;\n  label: string;\n  value: number;\n  min: number;\n  max: number;\n  alertAt?: number;\n  defaultUnits?: \"us\" | \"metric\";\n}\n\nconst UNIT = { stage: \"ft\", flow: \"cfs\", temp: \"°F\" } as const;\n\nconst stage: Fixture = { kind: \"stage\", label: \"Stage\", value: 6.2, min: 0, max: 10, alertAt: 9 };\nconst flow: Fixture = { kind: \"flow\", label: \"Flow\", value: 4810, min: 0, max: 10000 };\nconst temp: Fixture = { kind: \"temp\", label: \"Temp\", value: 51, min: 32, max: 86 };\n\nconst html = ({ kind, label, defaultUnits, value, min, max, alertAt }: Fixture) =>\n  renderToString(\n    <Gauge kind={kind} label={label} defaultUnits={defaultUnits} reading={{ value, unit: UNIT[kind], min, max, alertAt }} />,\n  );\n\ndescribe(\"Gauge\", () => {\n  it(\"formats stage in feet with one decimal\", () => {\n    expect(html(stage)).toContain(\">6.2 ft</button>\");\n    expect(html({ ...stage, value: 7 })).toContain(\">7.0 ft</button>\");\n  });\n\n  it(\"formats flow with a thousands separator\", () => {\n    expect(html(flow)).toContain(\">4,810 cfs</button>\");\n  });\n\n  it(\"formats temperature as whole degrees\", () => {\n    expect(html(temp)).toContain(\">51°F</button>\");\n    expect(html({ ...temp, value: 51.6 })).toContain(\">52°F</button>\");\n  });\n\n  it(\"shows metric units when asked\", () => {\n    expect(html({ ...stage, defaultUnits: \"metric\" })).toContain(\">1.9 m</button>\");\n    expect(html({ ...flow, defaultUnits: \"metric\" })).toContain(\">136.2 m³/s</button>\");\n    expect(html({ ...temp, defaultUnits: \"metric\" })).toContain(\">11°C</button>\");\n  });\n\n  it(\"draws the bar as the reading's share of the range, clamped to 0–100%\", () => {\n    expect(html(stage)).toContain(\"width:62%\");\n    expect(html(temp)).toContain(\"width:35%\");\n    expect(html({ ...stage, value: 12 })).toContain(\"width:100%\");\n    expect(html({ ...stage, value: -1 })).toContain(\"width:0%\");\n    expect(html({ ...stage, min: 5, max: 5 })).toContain(\"width:0%\");\n  });\n\n  it(\"switches to the alert color at the alert threshold\", () => {\n    const calm = html(stage);\n    expect(calm).not.toContain(\"data-alert\");\n    expect(calm).toContain(`background:${GAUGE_COLORS.light.bar}`);\n\n    const high = html({ ...stage, value: 9 });\n    expect(high).toContain('data-alert=\"true\"');\n    expect(high).toContain(`background:${GAUGE_COLORS.light.alert}`);\n  });\n});\n"
